  ],
  "limits": {
   "review_rounds": 3,
   "corrections": 2,
   "check_fixes": 1,
   "retries": 1,
   "check_timeout_s": 1800
  },
  "on_blocked": "stop",
  "stages": [
   {
    "role": "context-scout",
    "provider": "claude-code",
    "model_class": "economy"
   },
   {
    "role": "registrar",
